args.new_string:
code_block: (node, view, getPos) => {
    const lang = node.attrs.language;
    if (lang !== 'dataviewjs') return null;

    const dom = document.createElement('div');
    dom.classList.add('dataview-block');

    const code = document.createElement('pre');
    code.classList.add('dv-code-part');
    dom.appendChild(code);

    const resultContainer = document.createElement('div');
    resultContainer.classList.add('dv-container');
    dom.appendChild(resultContainer);

    setTimeout(() => fetchDataview(node.textContent, resultContainer), 0);

    let debounceTimer;

    return {
        dom,
        contentDOM: code,
        update: (newNode) => {
            if (newNode.type !== node.type) return false;
            if (newNode.textContent !== node.textContent) {
                clearTimeout(debounceTimer);
                debounceTimer = setTimeout(() => fetchDataview(newNode.textContent, resultContainer), 500);
            }
            return true;
        }
    };
}

