async function fetchDataview(script, container) {
    try {
        console.log("[Dataview] Fetching for script:", script);
        container.innerHTML = '<div class="dv-loading">Executing query...</div>';
...
                code_block: (node, view, getPos) => {
                    const lang = node.attrs.language;
                    if (lang !== 'dataviewjs') return null;

                    console.log("[Dataview] Creating node view for code block");

                    const dom = document.createElement('div');
                    dom.classList.add('dataview-block');

                    const code = document.createElement('pre');
                    code.classList.add('dv-code-part');
                    dom.appendChild(code);

                    const resultContainer = document.createElement('div');
                    resultContainer.classList.add('dv-container');
                    dom.appendChild(resultContainer);

                    setTimeout(() => fetchDataview(node.textContent, resultContainer), 0);

                    let debounceTimer;
                    let lastFetchedContent = node.textContent;

                    return {
                        dom,
                        contentDOM: code,
                        update: (newNode) => {
                            console.log("[Dataview] Node update triggered");
                            if (newNode.type.name !== 'code_block') return false;

                            if (newNode.textContent !== lastFetchedContent) {
                                console.log("[Dataview] Content changed detected. Old:", lastFetchedContent, "New:", newNode.textContent);
                                lastFetchedContent = newNode.textContent;
                                clearTimeout(debounceTimer);
                                debounceTimer = setTimeout(() => {
                                    console.log("[Dataview] Debounce finished, triggering fetch");
                                    fetchDataview(newNode.textContent, resultContainer);
                                }, 800);
                            }
                            return true;
                        }
                    };
                }

