    update: (newNode) => {
        // Check if this is still a code_block (or 'fence' if used)
        if (newNode.type.name !== node.type.name) return false;

        if (newNode.textContent !== lastContent) {
            console.log("[Dataview] Content changed, debouncing fetch...");
            lastContent = newNode.textContent;
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(() => {
                fetchDataview(newNode.textContent, resultContainer);
            }, 1000);
        }
        return true;
    },
    ignoreMutation: (mutation) => {
        // Ignore any mutations that happen outside the code editor area
        // (Prevents browser extensions from triggering re-renders)
        if (mutation.type === 'selection') return false;
        return !code.contains(mutation.target);
    },
    stopEvent: (event) => {
        // Stop events in the result container from reaching the editor
        return resultContainer.contains(event.target);
    }
};

