async function serveStatic(path) {
    const isProd = process.env.NODE_ENV === "production";
    if (path === "/") path = "/index.html";

    // 1. Try serving from dist/ (Production assets)
    let file = Bun.file(`dist${path}`);
    if (await file.exists()) {
        return new Response(file);
    }

    // 2. If in development, allow falling back to root or public/
    // In production, we NEVER fall back to root to avoid exposing server code.
    if (!isProd) {
        file = Bun.file(`.${path}`);
        if (await file.exists()) {
            return new Response(file);
        }

        file = Bun.file(`public${path}`);
        if (await file.exists()) {
            return new Response(file);
        }
    }

    return new Response("Not Found", { status: 404 });
}

