}

:root {
  /* Electric Blue Vibrant Palette */
  --md-sys-color-primary: #0056fb;
  --md-sys-color-on-primary: #ffffff;
  --md-sys-color-primary-container: #e0e7ff;
  --md-sys-color-on-primary-container: #00195f;

  --md-sys-color-secondary: #4359ab;
  --md-sys-color-on-secondary: #ffffff;
  --md-sys-color-secondary-container: #dbe1ff;
  --md-sys-color-on-secondary-container: #001453;

  --md-sys-color-error: #ff5449;
  --md-sys-color-on-error: #ffffff;

  --md-sys-color-background: #fbfbff;
  --md-sys-color-on-background: #191b23;
  --md-sys-color-surface: #fbfbff;
  --md-sys-color-on-surface: #191b23;
  --md-sys-color-surface-variant: #e1e2ec;
  --md-sys-color-on-surface-variant: #44464f;
  --md-sys-color-outline: #757780;

  /* Typography & Shapes */
  --md-sys-typescale-body-large-font: "Roboto", system-ui, -apple-system, sans-serif;
  --md-sys-shape-corner-small: 0.5rem; /* 8px */
  --md-sys-shape-corner-medium: 0.75rem; /* 12px */
  --md-sys-shape-corner-large: 1rem; /* 16px */
  --md-sys-shape-corner-extra-large: 1.75rem; /* 28px */
  --md-sys-shape-corner-full: 62.4375rem; /* 999px */

  /* Elevation */
  --md-sys-elevation-1: 0rem 0.0625rem 0.1875rem 0.0625rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);
  --md-sys-elevation-2: 0rem 0.125rem 0.375rem 0.125rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);

  /* Legacy variable mappings */
  --bg-color: var(--md-sys-color-background);
  --card-bg: var(--md-sys-color-surface);
  --text-main: var(--md-sys-color-on-background);
  --accent: var(--md-sys-color-primary);
  --spacing: 1rem; /* 16px */
}

body {
  font-family: var(--md-sys-typescale-body-large-font);
  background-color: var(--bg-color);
  color: var(--text-main);
  margin: 0;
  padding: 0;
  height: 100vh;
  overflow: hidden;
}

/* 1. The Responsive Grid (No Media Queries!) */
.grid-container {
  display: grid;
  gap: var(--spacing);
  max-width: 75rem; /* 1200px */
  margin: 0 auto;
  /* Automatically fit as many columns as possible, but at least 18.75rem (300px) each */
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 18.75rem), 1fr));
}

/* Framework Root Wrapper */
#app {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
}

/* 2. The Split-Pane Wrapper */
.app-container { 
    display: grid; 
    /* grid-template-columns injected by JS */
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden; 
    position: relative; 
    width: 100%;
    height: 100%;
}

.app-container > * {
    min-width: 0;
}

/* 3. Sidebar */
.sidebar { 
    border-right: none;
    display: grid; 
    grid-template-rows: auto minmax(0, 1fr);
    background: var(--md-sys-color-surface-variant); 
    overflow: hidden;
    height: 100%;
}

.resizer {
    width: 0.75rem; /* 12px */
    cursor: col-resize;
    position: relative;
    flex-shrink: 0;
    z-index: 10;
    background: transparent;
    transition: background-color 0.2s;
}

/* The visual line */
.resizer::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
    width: 0.0625rem; /* 1px */
    background-color: var(--md-sys-color-outline);
    transform: translateX(-50%);
