    gap: 1.25rem;
    width: 100%;
    max-width: 25rem; /* 400px */
    padding: 2.5rem;
    background: var(--md-sys-color-surface-variant);
    border-radius: var(--md-sys-shape-corner-extra-large);
    box-shadow: var(--md-sys-elevation-2);
}

.create-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Utility */
.hidden {
    display: none !important;
}

.mobile-only {
    display: none !important;
}

@media (max-width: 48rem) {
    .mobile-only {
        display: inline-flex !important;
    }
}

.sync-status {
    font-size: 0.6rem;
    color: var(--md-sys-color-outline);
}

/* Toast */
.toast {
    position: absolute;
    top: 1.25rem; /* 20px */
    left: 1.25rem; /* 20px */
    background: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
    padding: 0.75rem 1.5rem; /* 12px 24px */
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-elevation-2);
    opacity: 0;
    transform: translateX(-1.25rem); /* -20px */
    transition: opacity 0.3s ease, transform 0.3s ease;
    z-index: 1000;
    pointer-events: none;
}

.toast.show {
    opacity: 1;
    transform: translateX(0);
}

.toast.error {
    background: var(--md-sys-color-error);
    color: var(--md-sys-color-on-error);
}

/* 6. Dataview Styles */
.dv-container {
    margin: 1.5rem 0;
    padding: 1rem;
    background: color-mix(in srgb, var(--md-sys-color-primary) 3%, #ffffff);
    border-radius: var(--md-sys-shape-corner-medium);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
    min-height: 3rem;
    position: relative;
    transition: opacity 0.3s ease;
}

.dv-container.loading {
    opacity: 0.6;
}

.dv-loading {
    font-size: 0.85rem;
    color: var(--md-sys-color-outline);
    font-style: italic;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.dv-loading::before {
    content: "";
    width: 1rem;
    height: 1rem;
    border: 0.125rem solid var(--md-sys-color-primary);
    border-top-color: transparent;
    border-radius: 50%;
    animation: dv-spin 1s linear infinite;
}

@keyframes dv-spin {
    to { transform: rotate(360deg); }
}

.dv-empty {
    color: var(--md-sys-color-outline);
    font-style: italic;
}

.dv-error {
    color: var(--md-sys-color-error);
    font-size: 0.85rem;
    padding: 0.5rem;
    border-left: 0.25rem solid var(--md-sys-color-error);
}

.dv-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0.5rem 0;
}

.dv-table th {
    text-align: left;
    padding: 0.75rem;
    border-bottom: 0.125rem solid var(--md-sys-color-surface-variant);
    font-weight: 600;
    color: var(--md-sys-color-secondary);
    font-size: 0.9rem;
}

.dv-table td {
    padding: 0.75rem;
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant);
    font-size: 0.95rem;
}

.dv-table tr:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 5%, transparent);
}

.dv-link {
    color: var(--md-sys-color-primary);
    text-decoration: underline;
    text-decoration-style: dotted;
    cursor: pointer;
    font-weight: 500;
}

.dv-link:hover {
    color: color-mix(in srgb, var(--md-sys-color-primary) 80%, black);
    text-decoration-style: solid;
}

.dv-list {
    margin: 0.5rem 0;
    padding-left: 1.5rem;
}

.dv-list li {
    margin-bottom: 0.25rem;
}

/* Milkdown Styles */
.milkdown-scroll-wrapper {
    flex: 1;
    overflow-y: auto;
    background: var(--md-sys-color-surface);
}

.milkdown .editor {
    padding: 2rem !important;
    max-width: 50rem !important;
    margin: 0 auto !important;
    outline: none !important;
}

.raw-meta-editor {
    width: 100%;
    min-height: 15rem;
    font-family: 'Fira Code', monospace;
    font-size: 0.9rem;
    padding: 1rem;
    border-radius: 0.5rem;
    border: 0.0625rem solid var(--md-sys-color-outline);
    background: color-mix(in srgb, var(--md-sys-color-on-surface) 4%, var(--md-sys-color-surface));
    color: var(--md-sys-color-on-surface);
    resize: vertical;
}

.header-btn {
    padding: 0.5rem !important;
    width: auto !important;
    min-width: 2.5rem;
    height: 2.5rem;
    background: transparent !important;
    color: var(--md-sys-color-on-surface) !important;
    border: none !important;
    border-radius: 0.5rem !important;
    box-shadow: none !important;
}

.header-btn:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.header-btn.active {
    background: var(--md-sys-color-primary-container) !important;
    color: var(--md-sys-color-on-primary-container) !important;
}

.btn-text {
    margin-left: 0.5rem;
    font-size: 0.9rem;
    font-weight: 600;
}

.mobile-menu-btn {
    display: none;
    background: transparent;
    border: none;
    color: var(--md-sys-color-primary);
    padding: 0 0.5rem;
    cursor: pointer;
}

/* 8. Mobile Responsiveness */
@media (max-width: 48rem) { /* 768px */
    .app-container {
        grid-template-columns: 1fr !important;
        grid-template-rows: 1fr !important;
    }

    .sidebar {
        display: none;
    }

    .resizer {
        display: none;
    }

    .editor-view {
        display: none;
    }

    .mobile-sidebar-open .sidebar {
        display: grid;
    }

    .mobile-sidebar-open .editor-view {
        display: none;
    }

    /* When sidebar is closed, show the editor */
    .app-container:not(.mobile-sidebar-open) .editor-view {
        display: grid;
    }

    .mobile-menu-btn {
        display: flex;
    }

    .tab-bar {
        padding-left: 0.25rem;
    }

    .create-form {
        max-width: 90vw;
        padding: 1.5rem;
    }

    .sidebar-header {
        padding: 0.5rem;
    }
}

/* 7. Tab Bar Styles */
.tab-bar {
    display: flex;
    background: var(--md-sys-color-surface-variant);
    overflow-x: auto;
    border-bottom: 0.0625rem solid var(--md-sys-color-outline);
    gap: 0.125rem;
    padding: 0.5rem 0.5rem 0 0.5rem;
}

.tab-item {
    padding: 0.5rem 1rem;
    background: var(--md-sys-color-surface);
    border-radius: 0.5rem 0.5rem 0 0;
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--md-sys-color-outline);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    border: 0.0625rem solid transparent;
    border-bottom: none;
    transition: background 0.2s, color 0.2s;
    white-space: nowrap;
    min-width: 5rem;
    max-width: 12rem;
}

.tab-item:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, var(--md-sys-color-surface));
    color: var(--md-sys-color-primary);
}

.tab-item.active {
    background: var(--md-sys-color-surface);
    color: var(--md-sys-color-primary);
    border-color: var(--md-sys-color-outline);
    box-shadow: 0 0.125rem 0 0 var(--md-sys-color-surface);
    z-index: 1;
}

.tab-title {
    overflow: hidden;
    text-overflow: ellipsis;
}

.tab-close {
    font-size: 1rem !important;
    opacity: 0.6;
    transition: opacity 0.2s;
}

.tab-close:hover {
    opacity: 1;
    color: var(--md-sys-color-error);
}

.tab-content {
    flex: 1;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
    min-width: 0;
}

/* Milkdown Implementation Styles */
.editor-instance-container {
    display: flex;
    flex-direction: column;
    height: 100%;
    width: 100%;
    overflow: hidden;
    min-width: 0;
}

.custom-toolbar {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.25rem 0.5rem;
    background: var(--md-sys-color-surface-variant);
    border-radius: 0.75rem;
    margin: 0 0.5rem;
    flex-wrap: wrap; /* Allow wrapping */
}

.editor-header {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    padding: 0.5rem 1rem;
    gap: 0.5rem;
    border-bottom: 0.0625rem solid var(--md-sys-color-outline-variant);
    flex-wrap: wrap; /* Allow header to grow if toolbar wraps */
}

.toolbar-btn {
    padding: 0.25rem !important;
    width: 2.25rem !important;
    height: 2.25rem;
    min-width: 0 !important;
    background: transparent !important;
    color: var(--md-sys-color-on-surface-variant) !important;
    border-radius: 0.5rem !important;
    display: flex;
    align-items: center;
    justify-content: center;
}

.toolbar-btn:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 12%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.toolbar-divider {
    width: 0.0625rem;
    height: 1.25rem;
    background: var(--md-sys-color-outline);
    margin: 0 0.125rem;
    opacity: 0.3;
}

.milkdown-scroll-wrapper {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    background: var(--md-sys-color-surface);
    width: 100%;
    min-height: 0;
}

.raw-meta-editor {
    width: 100%;
    min-height: 10rem;
    font-family: 'Fira Code', monospace;
    padding: 1rem;
    background: #1e1e1e;
    color: #d4d4d4;
    border: none;
    outline: none;
    border-radius: 0.5rem;
}

/* Ensure Milkdown editor fills the scrollable area */
.milkdown {
    height: auto;
    min-height: 100%;
}

.milkdown .editor {
    padding: 2rem !important;
    max-width: 55rem !important;
    width: 100%;
    margin: 0 auto !important;
    outline: none !important;
    min-height: 100%;
    white-space: pre-wrap;
    word-break: break-word;
}


/* Milkdown Table Styles */
.milkdown .editor table {
    width: 100%;
    border-collapse: collapse;
    margin: 1.5rem 0;
    table-layout: fixed;
}

.milkdown .editor table th,
.milkdown .editor table td {
    border: 0.0625rem solid var(--md-sys-color-outline-variant);
    padding: 0.75rem;
    min-width: 5rem;
}

.milkdown .editor table th {
    background-color: var(--md-sys-color-surface-variant);
    font-weight: 600;
}

.milkdown .editor table p {
    margin: 0;
}

.material-symbols-rounded {
  font-family: 'Material Symbols Rounded';
  font-weight: normal;
  font-style: normal;
  font-size: 1.5rem;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-feature-settings: 'liga';
  -webkit-font-smoothing: antialiased;
}

:root {
  /* Electric Blue Vibrant Palette */
  --md-sys-color-primary: #0056fb;
  --md-sys-color-on-primary: #ffffff;
  --md-sys-color-primary-container: #e0e7ff;
  --md-sys-color-on-primary-container: #00195f;

  --md-sys-color-secondary: #4359ab;
  --md-sys-color-on-secondary: #ffffff;
  --md-sys-color-secondary-container: #dbe1ff;
  --md-sys-color-on-secondary-container: #001453;

  --md-sys-color-error: #ff5449;
  --md-sys-color-on-error: #ffffff;

  --md-sys-color-background: #fbfbff;
  --md-sys-color-on-background: #191b23;
  --md-sys-color-surface: #fbfbff;
  --md-sys-color-on-surface: #191b23;
  --md-sys-color-surface-variant: #e1e2ec;
  --md-sys-color-on-surface-variant: #44464f;
  --md-sys-color-outline: #757780;

  /* Typography & Shapes */
  --md-sys-typescale-body-large-font: "Roboto", system-ui, -apple-system, sans-serif;
  --md-sys-shape-corner-small: 0.5rem; /* 8px */
  --md-sys-shape-corner-medium: 0.75rem; /* 12px */
  --md-sys-shape-corner-large: 1rem; /* 16px */
  --md-sys-shape-corner-extra-large: 1.75rem; /* 28px */
  --md-sys-shape-corner-full: 62.4375rem; /* 999px */

  /* Elevation */
  --md-sys-elevation-1: 0rem 0.0625rem 0.1875rem 0.0625rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);
  --md-sys-elevation-2: 0rem 0.125rem 0.375rem 0.125rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);

  /* Legacy variable mappings */
  --bg-color: var(--md-sys-color-background);
  --card-bg: var(--md-sys-color-surface);
  --text-main: var(--md-sys-color-on-background);
  --accent: var(--md-sys-color-primary);
  --spacing: 1rem; /* 16px */
}

body {
  font-family: var(--md-sys-typescale-body-large-font);
  background-color: var(--bg-color);
  color: var(--text-main);
  margin: 0;
  padding: 0;
  height: 100vh;
  overflow: hidden;
}

/* 1. The Responsive Grid (No Media Queries!) */
.grid-container {
  display: grid;
  gap: var(--spacing);
  max-width: 75rem; /* 1200px */
  margin: 0 auto;
  /* Automatically fit as many columns as possible, but at least 18.75rem (300px) each */
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 18.75rem), 1fr));
}

/* Framework Root Wrapper */
#app {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
}

/* 2. The Split-Pane Wrapper */
.app-container { 
    display: grid; 
    /* grid-template-columns injected by JS */
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden; 
    position: relative; 
    width: 100%;
    height: 100%;
}

.app-container > * {
    min-width: 0;
}

/* 3. Sidebar */
.sidebar { 
    border-right: none;
    display: grid; 
    grid-template-rows: auto minmax(0, 1fr);
    background: var(--md-sys-color-surface-variant); 
    overflow: hidden;
    height: 100%;
}

.resizer {
    width: 0.75rem; /* 12px */
    cursor: col-resize;
    position: relative;
    flex-shrink: 0;
    z-index: 10;
    background: transparent;
    transition: background-color 0.2s;
}

/* The visual line */
.resizer::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
    width: 0.0625rem; /* 1px */
    background-color: var(--md-sys-color-outline);
    transform: translateX(-50%);
    transition: width 0.2s, background-color 0.2s;
}

.resizer:hover::after, .resizer:active::after {
    width: 0.25rem; /* 4px */
    background-color: var(--md-sys-color-primary);
}

.resizer:hover {
    background-color: color-mix(in srgb, var(--md-sys-color-primary) 10%, transparent);
}

.search-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-width: 15rem;
}

.search-main {
    display: flex;
    gap: 0.25rem;
    width: 100%;
}

.search-input-wrapper {
    position: relative;
    flex: 1;
    display: flex;
    align-items: center;
}

.search-input-wrapper input {
    width: 100%;
    padding-right: 2.5rem !important;
}

.btn-clear-search {
    position: absolute;
    right: 0.25rem;
    background: transparent !important;
    border: none !important;
    color: var(--md-sys-color-outline) !important;
    padding: 0.25rem !important;
    width: 2rem;
    height: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.btn-clear-search .material-symbols-rounded {
    font-size: 1.25rem;
}

.btn-clear-search:hover {
    color: var(--md-sys-color-primary) !important;
}

#btn-toggle-advanced {
    padding: 0.5rem !important;
    font-size: 1.25rem !important;
    width: 3rem;
    background: transparent !important;
    color: var(--md-sys-color-primary) !important;
    border: none !important;
}

.advanced-search {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: color-mix(in srgb, var(--md-sys-color-primary) 5%, #ffffff);
    border-radius: var(--md-sys-shape-corner-small);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
}

.advanced-search select, .advanced-search input {
    width: 100%;
    font-size: 0.85rem !important;
    padding: 0.5rem 0.75rem !important;
}

.btn-save-search {
    font-size: 0.85rem !important;
    padding: 0.5rem !important;
    background: var(--md-sys-color-primary-container) !important;
    color: var(--md-sys-color-on-primary-container) !important;
    width: 100%;
    margin-top: 0.25rem;
    border-radius: var(--md-sys-shape-corner-small) !important;
}

.btn-save-search:hover {
    filter: brightness(0.95);
    box-shadow: var(--md-sys-elevation-1);
}

.sidebar-header {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem; /* 8px */
    padding: 1rem; /* 16px */
    background: var(--md-sys-color-surface-variant);
    align-items: center;
}

.menu-container {
    position: relative;
    display: inline-block;
}

.dropdown-content {
    position: absolute;
    top: 100%;
    left: 0;
    margin-top: 0.5rem;
    background: var(--md-sys-color-surface);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-elevation-2);
    z-index: 1000;
    min-width: 12rem;
    padding: 0.5rem;
}

.dropdown-content button {
    width: 100%;
    justify-content: flex-start;
    font-size: 1rem !important;
    padding: 0.75rem 1rem !important;
    border: none !important;
    background: transparent !important;
    color: var(--md-sys-color-on-surface) !important;
    border-radius: var(--md-sys-shape-corner-small) !important;
    box-shadow: none !important;
    font-weight: 500 !important;
}

.dropdown-content button:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.sidebar-header input, .sidebar-header select {
    flex: 1;
    min-width: 6.25rem; /* 100px */
}

.sidebar-header button {
    padding: 0.5rem 0.875rem;
    background: transparent;
    border: none;
    color: var(--md-sys-color-primary);
    font-weight: 700;
    font-size: 1.5rem;
    transition: background-color 0.2s, color 0.2s, transform 0.1s;
    box-shadow: none;
}

.sidebar-header button:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent);
    color: var(--md-sys-color-primary);
    box-shadow: none;
}

.sidebar-header button:active {
    transform: scale(0.95);
}

/* Sidebar cards */
.sidebar .card {
    padding: 0.75rem 1rem; /* 12px 16px */
    margin-bottom: 0.5rem; /* 8px */
    border-radius: var(--md-sys-shape-corner-medium);
    border: none;
    background: var(--md-sys-color-surface);
    box-shadow: var(--md-sys-elevation-1);
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.sidebar .card:hover {
    box-shadow: var(--md-sys-elevation-2);
    transform: translateY(-0.0625rem); /* -1px */
}

.sidebar .card h3 {
    font-size: 1.1rem;
    margin: 0 0 0.3125rem 0; /* 5px */
}

.sidebar .card-type {
    font-size: 0.7rem;
    text-transform: uppercase;
    color: var(--md-sys-color-primary);
    font-weight: bold;
}

.card-type-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
}

.card-icon {
    font-size: 1.1rem !important;
    color: var(--md-sys-color-primary);
}

.card-location {
    font-size: 0.85rem;
    color: var(--md-sys-color-outline);
}

#note-list { 
    overflow-y: auto; 
    padding: 0.625rem; /* 10px */
    min-height: 0;
}

/* 4. Main Editor Area */
.editor-view { 
    display: grid;
    background: var(--md-sys-color-surface);
    padding: 0;
    height: 100%;
    overflow: hidden;
    position: relative;
    min-width: 0;
    width: 100%;
}

#editor-container {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr);
    height: 100%;
    width: 100%;
    overflow: hidden;
    min-width: 0;
}

.empty-state {
    display: grid;
    place-items: center;
    color: var(--md-sys-color-outline);
    text-align: center;
    padding: 1.25rem; /* 20px */
    position: relative;
}

.empty-state-menu {
    position: absolute;
    top: 1rem;
    left: 1rem;
    z-index: 10;
}

.empty-state-icon {
    font-size: 4rem;
    margin-bottom: 1rem; /* 16px */
    display: block;
    opacity: 0.5;
}

#body-viewer, #body-editor { 
    overflow-y: auto;
    background: transparent;
    min-height: 0;
    max-width: 100%;
}

.body-viewer {
    padding: 1.5rem 2rem;
    font-size: 1.1rem;
    line-height: 1.6;
    color: var(--md-sys-color-on-surface);
    max-width: 100%;
    overflow-x: auto;
}

/* Toast UI Viewer Overrides to match theme */
.toastui-editor-contents {
    font-family: inherit !important;
    font-size: inherit !important;
    color: inherit !important;
}

/* Icon alignment */
.material-symbols-rounded {
    font-size: 1.5rem;
    vertical-align: middle;
}

.btn-primary {
    background: var(--md-sys-color-primary) !important;
    color: var(--md-sys-color-on-primary) !important;
}

/* Toast UI Editor Styles */
.toastui-editor-defaultUI {
    border: none !important;
}

.toastui-editor-toolbar {
    background-color: var(--md-sys-color-surface) !important;
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant) !important; /* 1px */
}

/* Metadata Form */
#metadata-form {
    max-height: 35vh; /* Using vh for a more reliable constraint than % */
    overflow-y: auto;
    background: var(--md-sys-color-surface);
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
}

/* View-only state for metadata */
#metadata-form.view-only {
    opacity: 0.9;
}

#metadata-form.view-only .meta-input {
    pointer-events: none;
    background: transparent !important;
    border-color: transparent !important;
}

#metadata-form.view-only #btn-add-prop,
#metadata-form.view-only .btn-delete-prop {
    display: none !important;
}

.metadata-form {
    padding: 1rem 1.5rem; /* 16px 24px */
}

.meta-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem; /* 16px */
    cursor: pointer;
    user-select: none;
}

.meta-title {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    display: flex;
    align-items: center;
    letter-spacing: 0.0125rem; /* 0.2px */
}

.meta-toggle-icon {
    margin-right: 0.75rem; /* 12px */
    width: 1.5rem;
    font-size: 1.5rem !important;
    color: var(--md-sys-color-outline);
    transition: transform 0.2s ease;
    transform: rotate(-90deg); /* Start collapsed */
    display: inline-block;
}

.btn-add-prop {
    font-size: 0.75rem;
    padding: 0.375rem 1rem; /* 6px 16px */
    height: 2rem; /* 32px */
    background: transparent;
    border: 0.0625rem solid var(--md-sys-color-outline); /* 1px */
    color: var(--md-sys-color-primary);
}

.btn-add-prop:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent);
    border-color: var(--md-sys-color-primary);
}

#fields-container {
    display: flex;
    flex-direction: column;
    gap: 0.25rem; /* 4px */
    padding-bottom: 0.5rem; /* 8px */
}

.meta-field {
    display: grid;
    grid-template-columns: 7.5rem 1fr 2.5rem; /* 120px 1fr 40px */
    align-items: center;
    gap: 0.75rem; /* 12px */
    padding: 0.25rem 0.5rem; /* 4px 8px */
    border-radius: 0.5rem; /* 8px */
    transition: background-color 0.15s ease;
}

.meta-field:hover {
    background-color: color-mix(in srgb, var(--md-sys-color-on-surface) 4%, transparent);
}

.meta-label {
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--md-sys-color-secondary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-align: right;
}

.meta-input {
    width: 100%;
    padding: 0.5rem 0.75rem !important; /* 8px 12px */
    font-size: 0.9rem;
    border-radius: 0.25rem !important; /* 4px */
    border: 0.0625rem solid transparent !important; /* 1px */
    background: color-mix(in srgb, var(--md-sys-color-on-surface) 6%, transparent) !important;
    box-sizing: border-box;
}

.meta-input-number {
    max-width: 6.25rem; /* 100px */
}

.meta-input-date {
    max-width: 10rem; /* 160px */
}

.meta-input-text {
    max-width: 100%;
}

.meta-input:focus {
    background: var(--md-sys-color-surface) !important;
    border-color: var(--md-sys-color-primary) !important;
    box-shadow: 0 0 0 0.125rem color-mix(in srgb, var(--md-sys-color-primary) 15%, transparent); /* 2px */
}

/* Checkbox specific sizing */
.meta-input[type="checkbox"] {
    width: 1.125rem; /* 18px */
    height: 1.125rem; /* 18px */
    margin: 0;
    cursor: pointer;
    justify-self: start;
}

.btn-delete-prop {
    opacity: 0.6;
    background: transparent !important;
    color: var(--md-sys-color-outline) !important;
    padding: 0.5rem !important; /* 8px */
    font-size: 0.875rem; /* 14px */
    transition: opacity 0.2s, color 0.2s;
}

.btn-delete-prop:hover {
    opacity: 1;
    color: var(--md-sys-color-error) !important;
    background: color-mix(in srgb, var(--md-sys-color-error) 10%, transparent) !important;
}

.empty-meta-msg {
    color: var(--md-sys-color-outline);
    padding: 1.25rem; /* 20px */
}

/* --- M3 Base Elements --- */
button {
    font-family: var(--md-sys-typescale-body-large-font);
    font-weight: 500;
    border-radius: var(--md-sys-shape-corner-full);
    border: none;
    padding: 0.625rem 1.5rem; /* 10px 24px */
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s, filter 0.2s;
    background: var(--md-sys-color-secondary-container);
    color: var(--md-sys-color-on-secondary-container);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem; /* 8px */
}

button:hover {
    box-shadow: var(--md-sys-elevation-1);
    filter: brightness(0.95);
}

button:disabled {
    background: var(--md-sys-color-surface-variant) !important;
    color: var(--md-sys-color-outline) !important;
    cursor: not-allowed;
    box-shadow: none;
    filter: none;
}

input, select, textarea {
    font-family: inherit;
    padding: 0.75rem 1rem; /* 12px 16px */
    border-radius: var(--md-sys-shape-corner-small);
    border: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    background: color-mix(in srgb, var(--md-sys-color-primary) 3%, #ffffff);
    color: var(--md-sys-color-on-surface);
    box-sizing: border-box;
    transition: border-color 0.2s, background-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus, textarea:focus {
    outline: none;
    border-color: var(--md-sys-color-primary);
    background: #ffffff;
    box-shadow: 0 0 0 0.25rem color-mix(in srgb, var(--md-sys-color-primary) 15%, transparent);
}

/* Header & Footer */
.editor-header {
    padding: 0.75rem 1rem; /* 12px 16px */
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    display: flex;
    gap: 0.5rem; /* 8px */
    background: var(--md-sys-color-surface);
}

#btn-save, #btn-submit-create {
    background: var(--md-sys-color-primary);
    color: var(--md-sys-color-on-primary);
}

.btn-delete {
    background: var(--md-sys-color-error) !important;
    color: var(--md-sys-color-on-error) !important;
    margin-left: auto;
}

.editor-footer {
    padding: 0.625rem; /* 10px */
    font-size: 0.75rem;
    color: var(--md-sys-color-outline);
    border-top: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    background: var(--md-sys-color-surface-variant);
    text-align: right;
    height: 2.1875rem; /* 35px */
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

/* Create Note View */
.create-view {
    display: grid;
    place-items: center;
    height: 100%;
    width: 100%;
    background: var(--md-sys-color-surface);
}

.create-form {
    display: grid;
    gap: 1.25rem;
    width: 100%;
    max-width: 25rem; /* 400px */
    padding: 2.5rem;
    background: var(--md-sys-color-surface-variant);
    border-radius: var(--md-sys-shape-corner-extra-large);
    box-shadow: var(--md-sys-elevation-2);
}

.create-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Utility */
.hidden {
    display: none !important;
}

.mobile-only {
    display: none !important;
}

@media (max-width: 48rem) {
    .mobile-only {
        display: inline-flex !important;
    }
}

.sync-status {
    font-size: 0.6rem;
    color: var(--md-sys-color-outline);
}

/* Toast */
.toast {
    position: absolute;
    top: 1.25rem; /* 20px */
    left: 1.25rem; /* 20px */
    background: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
    padding: 0.75rem 1.5rem; /* 12px 24px */
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-elevation-2);
    opacity: 0;
    transform: translateX(-1.25rem); /* -20px */
    transition: opacity 0.3s ease, transform 0.3s ease;
    z-index: 1000;
    pointer-events: none;
}

.toast.show {
    opacity: 1;
    transform: translateX(0);
}

.toast.error {
    background: var(--md-sys-color-error);
    color: var(--md-sys-color-on-error);
}

/* 6. Dataview Styles */
.dv-container {
    margin: 1.5rem 0;
    padding: 1rem;
    background: color-mix(in srgb, var(--md-sys-color-primary) 3%, #ffffff);
    border-radius: var(--md-sys-shape-corner-medium);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
    min-height: 3rem;
    position: relative;
    transition: opacity 0.3s ease;
}

.dv-container.loading {
    opacity: 0.6;
}

.dv-loading {
    font-size: 0.85rem;
    color: var(--md-sys-color-outline);
    font-style: italic;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.dv-loading::before {
    content: "";
    width: 1rem;
    height: 1rem;
    border: 0.125rem solid var(--md-sys-color-primary);
    border-top-color: transparent;
    border-radius: 50%;
    animation: dv-spin 1s linear infinite;
}

@keyframes dv-spin {
    to { transform: rotate(360deg); }
}

.dv-empty {
    color: var(--md-sys-color-outline);
    font-style: italic;
}

.dv-error {
    color: var(--md-sys-color-error);
    font-size: 0.85rem;
    padding: 0.5rem;
    border-left: 0.25rem solid var(--md-sys-color-error);
}

.dv-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0.5rem 0;
}

.dv-table th {
    text-align: left;
    padding: 0.75rem;
    border-bottom: 0.125rem solid var(--md-sys-color-surface-variant);
    font-weight: 600;
    color: var(--md-sys-color-secondary);
    font-size: 0.9rem;
}

.dv-table td {
    padding: 0.75rem;
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant);
    font-size: 0.95rem;
}

.dv-table tr:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 5%, transparent);
}

.dv-link {
    color: var(--md-sys-color-primary);
    text-decoration: underline;
    text-decoration-style: dotted;
    cursor: pointer;
    font-weight: 500;
}

.dv-link:hover {
    color: color-mix(in srgb, var(--md-sys-color-primary) 80%, black);
    text-decoration-style: solid;
}

.dv-list {
    margin: 0.5rem 0;
    padding-left: 1.5rem;
}

.dv-list li {
    margin-bottom: 0.25rem;
}

/* Milkdown Styles */
.milkdown-scroll-wrapper {
    flex: 1;
    overflow-y: auto;
    background: var(--md-sys-color-surface);
}

.milkdown .editor {
    padding: 2rem !important;
    max-width: 50rem !important;
    margin: 0 auto !important;
    outline: none !important;
}

.raw-meta-editor {
    width: 100%;
    min-height: 15rem;
    font-family: 'Fira Code', monospace;
    font-size: 0.9rem;
    padding: 1rem;
    border-radius: 0.5rem;
    border: 0.0625rem solid var(--md-sys-color-outline);
    background: color-mix(in srgb, var(--md-sys-color-on-surface) 4%, var(--md-sys-color-surface));
    color: var(--md-sys-color-on-surface);
    resize: vertical;
}

.header-btn {
    padding: 0.5rem !important;
    width: auto !important;
    min-width: 2.5rem;
    height: 2.5rem;
    background: transparent !important;
    color: var(--md-sys-color-on-surface) !important;
    border: none !important;
    border-radius: 0.5rem !important;
    box-shadow: none !important;
}

.header-btn:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.header-btn.active {
    background: var(--md-sys-color-primary-container) !important;
    color: var(--md-sys-color-on-primary-container) !important;
}

.btn-text {
    margin-left: 0.5rem;
    font-size: 0.9rem;
    font-weight: 600;
}

.mobile-menu-btn {
    display: none;
    background: transparent;
    border: none;
    color: var(--md-sys-color-primary);
    padding: 0 0.5rem;
    cursor: pointer;
}

/* 8. Mobile Responsiveness */
@media (max-width: 48rem) { /* 768px */
    .app-container {
        grid-template-columns: 1fr !important;
        grid-template-rows: 1fr !important;
    }

    .sidebar {
        display: none;
    }

    .resizer {
        display: none;
    }

    .editor-view {
        display: none;
    }

    .mobile-sidebar-open .sidebar {
        display: grid;
    }

    .mobile-sidebar-open .editor-view {
        display: none;
    }

    /* When sidebar is closed, show the editor */
    .app-container:not(.mobile-sidebar-open) .editor-view {
        display: grid;
    }

    .mobile-menu-btn {
        display: flex;
    }

    .tab-bar {
        padding-left: 0.25rem;
    }

    .create-form {
        max-width: 90vw;
        padding: 1.5rem;
    }

    .sidebar-header {
        padding: 0.5rem;
    }
}

/* 7. Tab Bar Styles */
.tab-bar {
    display: flex;
    background: var(--md-sys-color-surface-variant);
    overflow-x: auto;
    border-bottom: 0.0625rem solid var(--md-sys-color-outline);
    gap: 0.125rem;
    padding: 0.5rem 0.5rem 0 0.5rem;
}

.tab-item {
    padding: 0.5rem 1rem;
    background: var(--md-sys-color-surface);
    border-radius: 0.5rem 0.5rem 0 0;
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--md-sys-color-outline);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    border: 0.0625rem solid transparent;
    border-bottom: none;
    transition: background 0.2s, color 0.2s;
    white-space: nowrap;
    min-width: 5rem;
    max-width: 12rem;
}

.tab-item:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, var(--md-sys-color-surface));
    color: var(--md-sys-color-primary);
}

.tab-item.active {
    background: var(--md-sys-color-surface);
    color: var(--md-sys-color-primary);
    border-color: var(--md-sys-color-outline);
    box-shadow: 0 0.125rem 0 0 var(--md-sys-color-surface);
    z-index: 1;
}

.tab-title {
    overflow: hidden;
    text-overflow: ellipsis;
}

.tab-close {
    font-size: 1rem !important;
    opacity: 0.6;
    transition: opacity 0.2s;
}

.tab-close:hover {
    opacity: 1;
    color: var(--md-sys-color-error);
}

.tab-content {
    flex: 1;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
    min-width: 0;
}

/* Milkdown Implementation Styles */
.editor-instance-container {
    display: flex;
    flex-direction: column;
    height: 100%;
    width: 100%;
    overflow: hidden;
    min-width: 0;
}

.custom-toolbar {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.25rem 0.5rem;
    background: var(--md-sys-color-surface-variant);
    border-radius: 0.75rem;
    margin: 0 0.5rem;
    flex-wrap: wrap; /* Allow wrapping */
}

.editor-header {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    padding: 0.5rem 1rem;
    gap: 0.5rem;
    border-bottom: 0.0625rem solid var(--md-sys-color-outline-variant);
    flex-wrap: wrap; /* Allow header to grow if toolbar wraps */
}

.toolbar-btn {
    padding: 0.25rem !important;
    width: 2.25rem !important;
    height: 2.25rem;
    min-width: 0 !important;
    background: transparent !important;
    color: var(--md-sys-color-on-surface-variant) !important;
    border-radius: 0.5rem !important;
    display: flex;
    align-items: center;
    justify-content: center;
}

.toolbar-btn:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 12%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.toolbar-divider {
    width: 0.0625rem;
    height: 1.25rem;
    background: var(--md-sys-color-outline);
    margin: 0 0.125rem;
    opacity: 0.3;
}

.milkdown-scroll-wrapper {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    background: var(--md-sys-color-surface);
    width: 100%;
    min-height: 0;
}

.raw-meta-editor {
    width: 100%;
    min-height: 10rem;
    font-family: 'Fira Code', monospace;
    padding: 1rem;
    background: #1e1e1e;
    color: #d4d4d4;
    border: none;
    outline: none;
    border-radius: 0.5rem;
}

/* Ensure Milkdown editor fills the scrollable area */
.milkdown {
    height: auto;
    min-height: 100%;
}

.milkdown .editor {
    padding: 2rem !important;
    max-width: 55rem !important;
    width: 100%;
    margin: 0 auto !important;
    outline: none !important;
    min-height: 100%;
    white-space: pre-wrap;
    word-break: break-word;
}


/* Milkdown Table Styles */
.milkdown .editor table {
    width: 100%;
    border-collapse: collapse;
    margin: 1.5rem 0;
    table-layout: fixed;
}

.milkdown .editor table th,
.milkdown .editor table td {
    border: 0.0625rem solid var(--md-sys-color-outline-variant);
    padding: 0.75rem;
    min-width: 5rem;
}

.milkdown .editor table th {
    background-color: var(--md-sys-color-surface-variant);
    font-weight: 600;
}

.milkdown .editor table p {
    margin: 0;
}

.material-symbols-rounded {
  font-family: 'Material Symbols Rounded';
  font-weight: normal;
  font-style: normal;
  font-size: 1.5rem;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-feature-settings: 'liga';
  -webkit-font-smoothing: antialiased;
}

:root {
  /* Electric Blue Vibrant Palette */
  --md-sys-color-primary: #0056fb;
  --md-sys-color-on-primary: #ffffff;
  --md-sys-color-primary-container: #e0e7ff;
  --md-sys-color-on-primary-container: #00195f;

  --md-sys-color-secondary: #4359ab;
  --md-sys-color-on-secondary: #ffffff;
  --md-sys-color-secondary-container: #dbe1ff;
  --md-sys-color-on-secondary-container: #001453;

  --md-sys-color-error: #ff5449;
  --md-sys-color-on-error: #ffffff;

  --md-sys-color-background: #fbfbff;
  --md-sys-color-on-background: #191b23;
  --md-sys-color-surface: #fbfbff;
  --md-sys-color-on-surface: #191b23;
  --md-sys-color-surface-variant: #e1e2ec;
  --md-sys-color-on-surface-variant: #44464f;
  --md-sys-color-outline: #757780;

  /* Typography & Shapes */
  --md-sys-typescale-body-large-font: "Roboto", system-ui, -apple-system, sans-serif;
  --md-sys-shape-corner-small: 0.5rem; /* 8px */
  --md-sys-shape-corner-medium: 0.75rem; /* 12px */
  --md-sys-shape-corner-large: 1rem; /* 16px */
  --md-sys-shape-corner-extra-large: 1.75rem; /* 28px */
  --md-sys-shape-corner-full: 62.4375rem; /* 999px */

  /* Elevation */
  --md-sys-elevation-1: 0rem 0.0625rem 0.1875rem 0.0625rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);
  --md-sys-elevation-2: 0rem 0.125rem 0.375rem 0.125rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);

  /* Legacy variable mappings */
  --bg-color: var(--md-sys-color-background);
  --card-bg: var(--md-sys-color-surface);
  --text-main: var(--md-sys-color-on-background);
  --accent: var(--md-sys-color-primary);
  --spacing: 1rem; /* 16px */
}

body {
  font-family: var(--md-sys-typescale-body-large-font);
  background-color: var(--bg-color);
  color: var(--text-main);
  margin: 0;
  padding: 0;
  height: 100vh;
  overflow: hidden;
}

/* 1. The Responsive Grid (No Media Queries!) */
.grid-container {
  display: grid;
  gap: var(--spacing);
  max-width: 75rem; /* 1200px */
  margin: 0 auto;
  /* Automatically fit as many columns as possible, but at least 18.75rem (300px) each */
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 18.75rem), 1fr));
}

/* Framework Root Wrapper */
#app {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
}

/* 2. The Split-Pane Wrapper */
.app-container { 
    display: grid; 
    /* grid-template-columns injected by JS */
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden; 
    position: relative; 
    width: 100%;
    height: 100%;
}

.app-container > * {
    min-width: 0;
}

/* 3. Sidebar */
.sidebar { 
    border-right: none;
    display: grid; 
    grid-template-rows: auto minmax(0, 1fr);
    background: var(--md-sys-color-surface-variant); 
    overflow: hidden;
    height: 100%;
}

.resizer {
    width: 0.75rem; /* 12px */
    cursor: col-resize;
    position: relative;
    flex-shrink: 0;
    z-index: 10;
    background: transparent;
    transition: background-color 0.2s;
}

/* The visual line */
.resizer::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
    width: 0.0625rem; /* 1px */
    background-color: var(--md-sys-color-outline);
    transform: translateX(-50%);
    transition: width 0.2s, background-color 0.2s;
}

.resizer:hover::after, .resizer:active::after {
    width: 0.25rem; /* 4px */
    background-color: var(--md-sys-color-primary);
}

.resizer:hover {
    background-color: color-mix(in srgb, var(--md-sys-color-primary) 10%, transparent);
}

.search-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-width: 15rem;
}

.search-main {
    display: flex;
    gap: 0.25rem;
    width: 100%;
}

.search-input-wrapper {
    position: relative;
    flex: 1;
    display: flex;
    align-items: center;
}

.search-input-wrapper input {
    width: 100%;
    padding-right: 2.5rem !important;
}

.btn-clear-search {
    position: absolute;
    right: 0.25rem;
    background: transparent !important;
    border: none !important;
    color: var(--md-sys-color-outline) !important;
    padding: 0.25rem !important;
    width: 2rem;
    height: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.btn-clear-search .material-symbols-rounded {
    font-size: 1.25rem;
}

.btn-clear-search:hover {
    color: var(--md-sys-color-primary) !important;
}

#btn-toggle-advanced {
    padding: 0.5rem !important;
    font-size: 1.25rem !important;
    width: 3rem;
    background: transparent !important;
    color: var(--md-sys-color-primary) !important;
    border: none !important;
}

.advanced-search {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: color-mix(in srgb, var(--md-sys-color-primary) 5%, #ffffff);
    border-radius: var(--md-sys-shape-corner-small);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
}

.advanced-search select, .advanced-search input {
    width: 100%;
    font-size: 0.85rem !important;
    padding: 0.5rem 0.75rem !important;
}

.btn-save-search {
    font-size: 0.85rem !important;
    padding: 0.5rem !important;
    background: var(--md-sys-color-primary-container) !important;
    color: var(--md-sys-color-on-primary-container) !important;
    width: 100%;
    margin-top: 0.25rem;
    border-radius: var(--md-sys-shape-corner-small) !important;
}

.btn-save-search:hover {
    filter: brightness(0.95);
    box-shadow: var(--md-sys-elevation-1);
}

.sidebar-header {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem; /* 8px */
    padding: 1rem; /* 16px */
    background: var(--md-sys-color-surface-variant);
    align-items: center;
}

.menu-container {
    position: relative;
    display: inline-block;
}

.dropdown-content {
    position: absolute;
    top: 100%;
    left: 0;
    margin-top: 0.5rem;
    background: var(--md-sys-color-surface);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-elevation-2);
    z-index: 1000;
    min-width: 12rem;
    padding: 0.5rem;
}

.dropdown-content button {
    width: 100%;
    justify-content: flex-start;
    font-size: 1rem !important;
    padding: 0.75rem 1rem !important;
    border: none !important;
    background: transparent !important;
    color: var(--md-sys-color-on-surface) !important;
    border-radius: var(--md-sys-shape-corner-small) !important;
    box-shadow: none !important;
    font-weight: 500 !important;
}

.dropdown-content button:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.sidebar-header input, .sidebar-header select {
    flex: 1;
    min-width: 6.25rem; /* 100px */
}

.sidebar-header button {
    padding: 0.5rem 0.875rem;
    background: transparent;
    border: none;
    color: var(--md-sys-color-primary);
    font-weight: 700;
    font-size: 1.5rem;
    transition: background-color 0.2s, color 0.2s, transform 0.1s;
    box-shadow: none;
}

.sidebar-header button:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent);
    color: var(--md-sys-color-primary);
    box-shadow: none;
}

.sidebar-header button:active {
    transform: scale(0.95);
}

/* Sidebar cards */
.sidebar .card {
    padding: 0.75rem 1rem; /* 12px 16px */
    margin-bottom: 0.5rem; /* 8px */
    border-radius: var(--md-sys-shape-corner-medium);
    border: none;
    background: var(--md-sys-color-surface);
    box-shadow: var(--md-sys-elevation-1);
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.sidebar .card:hover {
    box-shadow: var(--md-sys-elevation-2);
    transform: translateY(-0.0625rem); /* -1px */
}

.sidebar .card h3 {
    font-size: 1.1rem;
    margin: 0 0 0.3125rem 0; /* 5px */
}

.sidebar .card-type {
    font-size: 0.7rem;
    text-transform: uppercase;
    color: var(--md-sys-color-primary);
    font-weight: bold;
}

.card-type-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
}

.card-icon {
    font-size: 1.1rem !important;
    color: var(--md-sys-color-primary);
}

.card-location {
    font-size: 0.85rem;
    color: var(--md-sys-color-outline);
}

#note-list { 
    overflow-y: auto; 
    padding: 0.625rem; /* 10px */
    min-height: 0;
}

/* 4. Main Editor Area */
.editor-view { 
    display: grid;
    background: var(--md-sys-color-surface);
    padding: 0;
    height: 100%;
    overflow: hidden;
    position: relative;
    min-width: 0;
    width: 100%;
}

#editor-container {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr);
    height: 100%;
    width: 100%;
    overflow: hidden;
    min-width: 0;
}

.empty-state {
    display: grid;
    place-items: center;
    color: var(--md-sys-color-outline);
    text-align: center;
    padding: 1.25rem; /* 20px */
    position: relative;
}

.empty-state-menu {
    position: absolute;
    top: 1rem;
    left: 1rem;
    z-index: 10;
}

.empty-state-icon {
    font-size: 4rem;
    margin-bottom: 1rem; /* 16px */
    display: block;
    opacity: 0.5;
}

#body-viewer, #body-editor { 
    overflow-y: auto;
    background: transparent;
    min-height: 0;
    max-width: 100%;
}

.body-viewer {
    padding: 1.5rem 2rem;
    font-size: 1.1rem;
    line-height: 1.6;
    color: var(--md-sys-color-on-surface);
    max-width: 100%;
    overflow-x: auto;
}

/* Toast UI Viewer Overrides to match theme */
.toastui-editor-contents {
    font-family: inherit !important;
    font-size: inherit !important;
    color: inherit !important;
}

/* Icon alignment */
.material-symbols-rounded {
    font-size: 1.5rem;
    vertical-align: middle;
}

.btn-primary {
    background: var(--md-sys-color-primary) !important;
    color: var(--md-sys-color-on-primary) !important;
}

/* Toast UI Editor Styles */
.toastui-editor-defaultUI {
    border: none !important;
}

.toastui-editor-toolbar {
    background-color: var(--md-sys-color-surface) !important;
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant) !important; /* 1px */
}

/* Metadata Form */
#metadata-form {
    max-height: 35vh; /* Using vh for a more reliable constraint than % */
    overflow-y: auto;
    background: var(--md-sys-color-surface);
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
}

/* View-only state for metadata */
#metadata-form.view-only {
    opacity: 0.9;
}

#metadata-form.view-only .meta-input {
    pointer-events: none;
    background: transparent !important;
    border-color: transparent !important;
}

#metadata-form.view-only #btn-add-prop,
#metadata-form.view-only .btn-delete-prop {
    display: none !important;
}

.metadata-form {
    padding: 1rem 1.5rem; /* 16px 24px */
}

.meta-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem; /* 16px */
    cursor: pointer;
    user-select: none;
}

.meta-title {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    display: flex;
    align-items: center;
    letter-spacing: 0.0125rem; /* 0.2px */
}

.meta-toggle-icon {
    margin-right: 0.75rem; /* 12px */
    width: 1.5rem;
    font-size: 1.5rem !important;
    color: var(--md-sys-color-outline);
    transition: transform 0.2s ease;
    transform: rotate(-90deg); /* Start collapsed */
    display: inline-block;
}

.btn-add-prop {
    font-size: 0.75rem;
    padding: 0.375rem 1rem; /* 6px 16px */
    height: 2rem; /* 32px */
    background: transparent;
    border: 0.0625rem solid var(--md-sys-color-outline); /* 1px */
    color: var(--md-sys-color-primary);
}

.btn-add-prop:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent);
    border-color: var(--md-sys-color-primary);
}

#fields-container {
    display: flex;
    flex-direction: column;
    gap: 0.25rem; /* 4px */
    padding-bottom: 0.5rem; /* 8px */
}

.meta-field {
    display: grid;
    grid-template-columns: 7.5rem 1fr 2.5rem; /* 120px 1fr 40px */
    align-items: center;
    gap: 0.75rem; /* 12px */
    padding: 0.25rem 0.5rem; /* 4px 8px */
    border-radius: 0.5rem; /* 8px */
    transition: background-color 0.15s ease;
}

.meta-field:hover {
    background-color: color-mix(in srgb, var(--md-sys-color-on-surface) 4%, transparent);
}

.meta-label {
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--md-sys-color-secondary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-align: right;
}

.meta-input {
    width: 100%;
    padding: 0.5rem 0.75rem !important; /* 8px 12px */
    font-size: 0.9rem;
    border-radius: 0.25rem !important; /* 4px */
    border: 0.0625rem solid transparent !important; /* 1px */
    background: color-mix(in srgb, var(--md-sys-color-on-surface) 6%, transparent) !important;
    box-sizing: border-box;
}

.meta-input-number {
    max-width: 6.25rem; /* 100px */
}

.meta-input-date {
    max-width: 10rem; /* 160px */
}

.meta-input-text {
    max-width: 100%;
}

.meta-input:focus {
    background: var(--md-sys-color-surface) !important;
    border-color: var(--md-sys-color-primary) !important;
    box-shadow: 0 0 0 0.125rem color-mix(in srgb, var(--md-sys-color-primary) 15%, transparent); /* 2px */
}

/* Checkbox specific sizing */
.meta-input[type="checkbox"] {
    width: 1.125rem; /* 18px */
    height: 1.125rem; /* 18px */
    margin: 0;
    cursor: pointer;
    justify-self: start;
}

.btn-delete-prop {
    opacity: 0.6;
    background: transparent !important;
    color: var(--md-sys-color-outline) !important;
    padding: 0.5rem !important; /* 8px */
    font-size: 0.875rem; /* 14px */
    transition: opacity 0.2s, color 0.2s;
}

.btn-delete-prop:hover {
    opacity: 1;
    color: var(--md-sys-color-error) !important;
    background: color-mix(in srgb, var(--md-sys-color-error) 10%, transparent) !important;
}

.empty-meta-msg {
    color: var(--md-sys-color-outline);
    padding: 1.25rem; /* 20px */
}

/* --- M3 Base Elements --- */
button {
    font-family: var(--md-sys-typescale-body-large-font);
    font-weight: 500;
    border-radius: var(--md-sys-shape-corner-full);
    border: none;
    padding: 0.625rem 1.5rem; /* 10px 24px */
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s, filter 0.2s;
    background: var(--md-sys-color-secondary-container);
    color: var(--md-sys-color-on-secondary-container);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem; /* 8px */
}

button:hover {
    box-shadow: var(--md-sys-elevation-1);
    filter: brightness(0.95);
}

button:disabled {
    background: var(--md-sys-color-surface-variant) !important;
    color: var(--md-sys-color-outline) !important;
    cursor: not-allowed;
    box-shadow: none;
    filter: none;
}

input, select, textarea {
    font-family: inherit;
    padding: 0.75rem 1rem; /* 12px 16px */
    border-radius: var(--md-sys-shape-corner-small);
    border: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    background: color-mix(in srgb, var(--md-sys-color-primary) 3%, #ffffff);
    color: var(--md-sys-color-on-surface);
    box-sizing: border-box;
    transition: border-color 0.2s, background-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus, textarea:focus {
    outline: none;
    border-color: var(--md-sys-color-primary);
    background: #ffffff;
    box-shadow: 0 0 0 0.25rem color-mix(in srgb, var(--md-sys-color-primary) 15%, transparent);
}

/* Header & Footer */
.editor-header {
    padding: 0.75rem 1rem; /* 12px 16px */
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    display: flex;
    gap: 0.5rem; /* 8px */
    background: var(--md-sys-color-surface);
}

#btn-save, #btn-submit-create {
    background: var(--md-sys-color-primary);
    color: var(--md-sys-color-on-primary);
}

.btn-delete {
    background: var(--md-sys-color-error) !important;
    color: var(--md-sys-color-on-error) !important;
    margin-left: auto;
}

.editor-footer {
    padding: 0.625rem; /* 10px */
    font-size: 0.75rem;
    color: var(--md-sys-color-outline);
    border-top: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    background: var(--md-sys-color-surface-variant);
    text-align: right;
    height: 2.1875rem; /* 35px */
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

/* Create Note View */
.create-view {
    display: grid;
    place-items: center;
    height: 100%;
    width: 100%;
    background: var(--md-sys-color-surface);
}

.create-form {
    display: grid;
    gap: 1.25rem;
    width: 100%;
    max-width: 25rem; /* 400px */
    padding: 2.5rem;
    background: var(--md-sys-color-surface-variant);
    border-radius: var(--md-sys-shape-corner-extra-large);
    box-shadow: var(--md-sys-elevation-2);
}

.create-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Utility */
.hidden {
    display: none !important;
}

.mobile-only {
    display: none !important;
}

@media (max-width: 48rem) {
    .mobile-only {
        display: inline-flex !important;
    }
}

.sync-status {
    font-size: 0.6rem;
    color: var(--md-sys-color-outline);
}

/* Toast */
.toast {
    position: absolute;
    top: 1.25rem; /* 20px */
    left: 1.25rem; /* 20px */
    background: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
    padding: 0.75rem 1.5rem; /* 12px 24px */
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-elevation-2);
    opacity: 0;
    transform: translateX(-1.25rem); /* -20px */
    transition: opacity 0.3s ease, transform 0.3s ease;
    z-index: 1000;
    pointer-events: none;
}

.toast.show {
    opacity: 1;
    transform: translateX(0);
}

.toast.error {
    background: var(--md-sys-color-error);
    color: var(--md-sys-color-on-error);
}

/* 6. Dataview Styles */
.dv-container {
    margin: 1.5rem 0;
    padding: 1rem;
    background: color-mix(in srgb, var(--md-sys-color-primary) 3%, #ffffff);
    border-radius: var(--md-sys-shape-corner-medium);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
    min-height: 3rem;
    position: relative;
    transition: opacity 0.3s ease;
}

.dv-container.loading {
    opacity: 0.6;
}

.dv-loading {
    font-size: 0.85rem;
    color: var(--md-sys-color-outline);
    font-style: italic;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.dv-loading::before {
    content: "";
    width: 1rem;
    height: 1rem;
    border: 0.125rem solid var(--md-sys-color-primary);
    border-top-color: transparent;
    border-radius: 50%;
    animation: dv-spin 1s linear infinite;
}

@keyframes dv-spin {
    to { transform: rotate(360deg); }
}

.dv-empty {
    color: var(--md-sys-color-outline);
    font-style: italic;
}

.dv-error {
    color: var(--md-sys-color-error);
    font-size: 0.85rem;
    padding: 0.5rem;
    border-left: 0.25rem solid var(--md-sys-color-error);
}

.dv-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0.5rem 0;
}

.dv-table th {
    text-align: left;
    padding: 0.75rem;
    border-bottom: 0.125rem solid var(--md-sys-color-surface-variant);
    font-weight: 600;
    color: var(--md-sys-color-secondary);
    font-size: 0.9rem;
}

.dv-table td {
    padding: 0.75rem;
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant);
    font-size: 0.95rem;
}

.dv-table tr:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 5%, transparent);
}

.dv-link {
    color: var(--md-sys-color-primary);
    text-decoration: underline;
    text-decoration-style: dotted;
    cursor: pointer;
    font-weight: 500;
}

.dv-link:hover {
    color: color-mix(in srgb, var(--md-sys-color-primary) 80%, black);
    text-decoration-style: solid;
}

.dv-list {
    margin: 0.5rem 0;
    padding-left: 1.5rem;
}

.dv-list li {
    margin-bottom: 0.25rem;
}

/* Milkdown Styles */
.milkdown-scroll-wrapper {
    flex: 1;
    overflow-y: auto;
    background: var(--md-sys-color-surface);
}

.milkdown .editor {
    padding: 2rem !important;
    max-width: 50rem !important;
    margin: 0 auto !important;
    outline: none !important;
}

.raw-meta-editor {
    width: 100%;
    min-height: 15rem;
    font-family: 'Fira Code', monospace;
    font-size: 0.9rem;
    padding: 1rem;
    border-radius: 0.5rem;
    border: 0.0625rem solid var(--md-sys-color-outline);
    background: color-mix(in srgb, var(--md-sys-color-on-surface) 4%, var(--md-sys-color-surface));
    color: var(--md-sys-color-on-surface);
    resize: vertical;
}

.header-btn {
    padding: 0.5rem !important;
    width: auto !important;
    min-width: 2.5rem;
    height: 2.5rem;
    background: transparent !important;
    color: var(--md-sys-color-on-surface) !important;
    border: none !important;
    border-radius: 0.5rem !important;
    box-shadow: none !important;
}

.header-btn:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.header-btn.active {
    background: var(--md-sys-color-primary-container) !important;
    color: var(--md-sys-color-on-primary-container) !important;
}

.btn-text {
    margin-left: 0.5rem;
    font-size: 0.9rem;
    font-weight: 600;
}

.mobile-menu-btn {
    display: none;
    background: transparent;
    border: none;
    color: var(--md-sys-color-primary);
    padding: 0 0.5rem;
    cursor: pointer;
}

/* 8. Mobile Responsiveness */
@media (max-width: 48rem) { /* 768px */
    .app-container {
        grid-template-columns: 1fr !important;
        grid-template-rows: 1fr !important;
    }

    .sidebar {
        display: none;
    }

    .resizer {
        display: none;
    }

    .editor-view {
        display: none;
    }

    .mobile-sidebar-open .sidebar {
        display: grid;
    }

    .mobile-sidebar-open .editor-view {
        display: none;
    }

    /* When sidebar is closed, show the editor */
    .app-container:not(.mobile-sidebar-open) .editor-view {
        display: grid;
    }

    .mobile-menu-btn {
        display: flex;
    }

    .tab-bar {
        padding-left: 0.25rem;
    }

    .create-form {
        max-width: 90vw;
        padding: 1.5rem;
    }

    .sidebar-header {
        padding: 0.5rem;
    }
}

/* 7. Tab Bar Styles */
.tab-bar {
    display: flex;
    background: var(--md-sys-color-surface-variant);
    overflow-x: auto;
    border-bottom: 0.0625rem solid var(--md-sys-color-outline);
    gap: 0.125rem;
    padding: 0.5rem 0.5rem 0 0.5rem;
}

.tab-item {
    padding: 0.5rem 1rem;
    background: var(--md-sys-color-surface);
    border-radius: 0.5rem 0.5rem 0 0;
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--md-sys-color-outline);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    border: 0.0625rem solid transparent;
    border-bottom: none;
    transition: background 0.2s, color 0.2s;
    white-space: nowrap;
    min-width: 5rem;
    max-width: 12rem;
}

.tab-item:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, var(--md-sys-color-surface));
    color: var(--md-sys-color-primary);
}

.tab-item.active {
    background: var(--md-sys-color-surface);
    color: var(--md-sys-color-primary);
    border-color: var(--md-sys-color-outline);
    box-shadow: 0 0.125rem 0 0 var(--md-sys-color-surface);
    z-index: 1;
}

.tab-title {
    overflow: hidden;
    text-overflow: ellipsis;
}

.tab-close {
    font-size: 1rem !important;
    opacity: 0.6;
    transition: opacity 0.2s;
}

.tab-close:hover {
    opacity: 1;
    color: var(--md-sys-color-error);
}

.tab-content {
    flex: 1;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
    min-width: 0;
}

/* Milkdown Implementation Styles */
.editor-instance-container {
    display: flex;
    flex-direction: column;
    height: 100%;
    width: 100%;
    overflow: hidden;
    min-width: 0;
}

.custom-toolbar {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.25rem 0.5rem;
    background: var(--md-sys-color-surface-variant);
    border-radius: 0.75rem;
    margin: 0 0.5rem;
    flex-wrap: wrap; /* Allow wrapping */
}

.editor-header {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    padding: 0.5rem 1rem;
    gap: 0.5rem;
    border-bottom: 0.0625rem solid var(--md-sys-color-outline-variant);
    flex-wrap: wrap; /* Allow header to grow if toolbar wraps */
}

.toolbar-btn {
    padding: 0.25rem !important;
    width: 2.25rem !important;
    height: 2.25rem;
    min-width: 0 !important;
    background: transparent !important;
    color: var(--md-sys-color-on-surface-variant) !important;
    border-radius: 0.5rem !important;
    display: flex;
    align-items: center;
    justify-content: center;
}

.toolbar-btn:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 12%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.toolbar-divider {
    width: 0.0625rem;
    height: 1.25rem;
    background: var(--md-sys-color-outline);
    margin: 0 0.125rem;
    opacity: 0.3;
}

.milkdown-scroll-wrapper {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    background: var(--md-sys-color-surface);
    width: 100%;
    min-height: 0;
}

.raw-meta-editor {
    width: 100%;
    min-height: 10rem;
    font-family: 'Fira Code', monospace;
    padding: 1rem;
    background: #1e1e1e;
    color: #d4d4d4;
    border: none;
    outline: none;
    border-radius: 0.5rem;
}

/* Ensure Milkdown editor fills the scrollable area */
.milkdown {
    height: auto;
    min-height: 100%;
}

.milkdown .editor {
    padding: 2rem !important;
    max-width: 55rem !important;
    width: 100%;
    margin: 0 auto !important;
    outline: none !important;
    min-height: 100%;
    white-space: pre-wrap;
    word-break: break-word;
}


/* Milkdown Table Styles */
.milkdown .editor table {
    width: 100%;
    border-collapse: collapse;
    margin: 1.5rem 0;
    table-layout: fixed;
}

.milkdown .editor table th,
.milkdown .editor table td {
    border: 0.0625rem solid var(--md-sys-color-outline-variant);
    padding: 0.75rem;
    min-width: 5rem;
}

.milkdown .editor table th {
    background-color: var(--md-sys-color-surface-variant);
    font-weight: 600;
}

.milkdown .editor table p {
    margin: 0;
}

.material-symbols-rounded {
  font-family: 'Material Symbols Rounded';
  font-weight: normal;
  font-style: normal;
  font-size: 1.5rem;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-feature-settings: 'liga';
  -webkit-font-smoothing: antialiased;
}

:root {
  /* Electric Blue Vibrant Palette */
  --md-sys-color-primary: #0056fb;
  --md-sys-color-on-primary: #ffffff;
  --md-sys-color-primary-container: #e0e7ff;
  --md-sys-color-on-primary-container: #00195f;

  --md-sys-color-secondary: #4359ab;
  --md-sys-color-on-secondary: #ffffff;
  --md-sys-color-secondary-container: #dbe1ff;
  --md-sys-color-on-secondary-container: #001453;

  --md-sys-color-error: #ff5449;
  --md-sys-color-on-error: #ffffff;

  --md-sys-color-background: #fbfbff;
  --md-sys-color-on-background: #191b23;
  --md-sys-color-surface: #fbfbff;
  --md-sys-color-on-surface: #191b23;
  --md-sys-color-surface-variant: #e1e2ec;
  --md-sys-color-on-surface-variant: #44464f;
  --md-sys-color-outline: #757780;

  /* Typography & Shapes */
  --md-sys-typescale-body-large-font: "Roboto", system-ui, -apple-system, sans-serif;
  --md-sys-shape-corner-small: 0.5rem; /* 8px */
  --md-sys-shape-corner-medium: 0.75rem; /* 12px */
  --md-sys-shape-corner-large: 1rem; /* 16px */
  --md-sys-shape-corner-extra-large: 1.75rem; /* 28px */
  --md-sys-shape-corner-full: 62.4375rem; /* 999px */

  /* Elevation */
  --md-sys-elevation-1: 0rem 0.0625rem 0.1875rem 0.0625rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);
  --md-sys-elevation-2: 0rem 0.125rem 0.375rem 0.125rem rgba(0, 0, 0, 0.15), 0rem 0.0625rem 0.125rem 0rem rgba(0, 0, 0, 0.3);

  /* Legacy variable mappings */
  --bg-color: var(--md-sys-color-background);
  --card-bg: var(--md-sys-color-surface);
  --text-main: var(--md-sys-color-on-background);
  --accent: var(--md-sys-color-primary);
  --spacing: 1rem; /* 16px */
}

body {
  font-family: var(--md-sys-typescale-body-large-font);
  background-color: var(--bg-color);
  color: var(--text-main);
  margin: 0;
  padding: 0;
  height: 100vh;
  overflow: hidden;
}

/* 1. The Responsive Grid (No Media Queries!) */
.grid-container {
  display: grid;
  gap: var(--spacing);
  max-width: 75rem; /* 1200px */
  margin: 0 auto;
  /* Automatically fit as many columns as possible, but at least 18.75rem (300px) each */
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 18.75rem), 1fr));
}

/* Framework Root Wrapper */
#app {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
}

/* 2. The Split-Pane Wrapper */
.app-container { 
    display: grid; 
    /* grid-template-columns injected by JS */
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden; 
    position: relative; 
    width: 100%;
    height: 100%;
}

.app-container > * {
    min-width: 0;
}

/* 3. Sidebar */
.sidebar { 
    border-right: none;
    display: grid; 
    grid-template-rows: auto minmax(0, 1fr);
    background: var(--md-sys-color-surface-variant); 
    overflow: hidden;
    height: 100%;
}

.resizer {
    width: 0.75rem; /* 12px */
    cursor: col-resize;
    position: relative;
    flex-shrink: 0;
    z-index: 10;
    background: transparent;
    transition: background-color 0.2s;
}

/* The visual line */
.resizer::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
    width: 0.0625rem; /* 1px */
    background-color: var(--md-sys-color-outline);
    transform: translateX(-50%);
    transition: width 0.2s, background-color 0.2s;
}

.resizer:hover::after, .resizer:active::after {
    width: 0.25rem; /* 4px */
    background-color: var(--md-sys-color-primary);
}

.resizer:hover {
    background-color: color-mix(in srgb, var(--md-sys-color-primary) 10%, transparent);
}

.search-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-width: 15rem;
}

.search-main {
    display: flex;
    gap: 0.25rem;
    width: 100%;
}

.search-input-wrapper {
    position: relative;
    flex: 1;
    display: flex;
    align-items: center;
}

.search-input-wrapper input {
    width: 100%;
    padding-right: 2.5rem !important;
}

.btn-clear-search {
    position: absolute;
    right: 0.25rem;
    background: transparent !important;
    border: none !important;
    color: var(--md-sys-color-outline) !important;
    padding: 0.25rem !important;
    width: 2rem;
    height: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.btn-clear-search .material-symbols-rounded {
    font-size: 1.25rem;
}

.btn-clear-search:hover {
    color: var(--md-sys-color-primary) !important;
}

#btn-toggle-advanced {
    padding: 0.5rem !important;
    font-size: 1.25rem !important;
    width: 3rem;
    background: transparent !important;
    color: var(--md-sys-color-primary) !important;
    border: none !important;
}

.advanced-search {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: color-mix(in srgb, var(--md-sys-color-primary) 5%, #ffffff);
    border-radius: var(--md-sys-shape-corner-small);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
}

.advanced-search select, .advanced-search input {
    width: 100%;
    font-size: 0.85rem !important;
    padding: 0.5rem 0.75rem !important;
}

.btn-save-search {
    font-size: 0.85rem !important;
    padding: 0.5rem !important;
    background: var(--md-sys-color-primary-container) !important;
    color: var(--md-sys-color-on-primary-container) !important;
    width: 100%;
    margin-top: 0.25rem;
    border-radius: var(--md-sys-shape-corner-small) !important;
}

.btn-save-search:hover {
    filter: brightness(0.95);
    box-shadow: var(--md-sys-elevation-1);
}

.sidebar-header {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem; /* 8px */
    padding: 1rem; /* 16px */
    background: var(--md-sys-color-surface-variant);
    align-items: center;
}

.menu-container {
    position: relative;
    display: inline-block;
}

.dropdown-content {
    position: absolute;
    top: 100%;
    left: 0;
    margin-top: 0.5rem;
    background: var(--md-sys-color-surface);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-elevation-2);
    z-index: 1000;
    min-width: 12rem;
    padding: 0.5rem;
}

.dropdown-content button {
    width: 100%;
    justify-content: flex-start;
    font-size: 1rem !important;
    padding: 0.75rem 1rem !important;
    border: none !important;
    background: transparent !important;
    color: var(--md-sys-color-on-surface) !important;
    border-radius: var(--md-sys-shape-corner-small) !important;
    box-shadow: none !important;
    font-weight: 500 !important;
}

.dropdown-content button:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent) !important;
    color: var(--md-sys-color-primary) !important;
}

.sidebar-header input, .sidebar-header select {
    flex: 1;
    min-width: 6.25rem; /* 100px */
}

.sidebar-header button {
    padding: 0.5rem 0.875rem;
    background: transparent;
    border: none;
    color: var(--md-sys-color-primary);
    font-weight: 700;
    font-size: 1.5rem;
    transition: background-color 0.2s, color 0.2s, transform 0.1s;
    box-shadow: none;
}

.sidebar-header button:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent);
    color: var(--md-sys-color-primary);
    box-shadow: none;
}

.sidebar-header button:active {
    transform: scale(0.95);
}

/* Sidebar cards */
.sidebar .card {
    padding: 0.75rem 1rem; /* 12px 16px */
    margin-bottom: 0.5rem; /* 8px */
    border-radius: var(--md-sys-shape-corner-medium);
    border: none;
    background: var(--md-sys-color-surface);
    box-shadow: var(--md-sys-elevation-1);
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.sidebar .card:hover {
    box-shadow: var(--md-sys-elevation-2);
    transform: translateY(-0.0625rem); /* -1px */
}

.sidebar .card h3 {
    font-size: 1.1rem;
    margin: 0 0 0.3125rem 0; /* 5px */
}

.sidebar .card-type {
    font-size: 0.7rem;
    text-transform: uppercase;
    color: var(--md-sys-color-primary);
    font-weight: bold;
}

.card-type-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
}

.card-icon {
    font-size: 1.1rem !important;
    color: var(--md-sys-color-primary);
}

.card-location {
    font-size: 0.85rem;
    color: var(--md-sys-color-outline);
}

#note-list { 
    overflow-y: auto; 
    padding: 0.625rem; /* 10px */
    min-height: 0;
}

/* 4. Main Editor Area */
.editor-view { 
    display: grid;
    background: var(--md-sys-color-surface);
    padding: 0;
    height: 100%;
    overflow: hidden;
    position: relative;
    min-width: 0;
    width: 100%;
}

#editor-container {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr);
    height: 100%;
    width: 100%;
    overflow: hidden;
    min-width: 0;
}

.empty-state {
    display: grid;
    place-items: center;
    color: var(--md-sys-color-outline);
    text-align: center;
    padding: 1.25rem; /* 20px */
    position: relative;
}

.empty-state-menu {
    position: absolute;
    top: 1rem;
    left: 1rem;
    z-index: 10;
}

.empty-state-icon {
    font-size: 4rem;
    margin-bottom: 1rem; /* 16px */
    display: block;
    opacity: 0.5;
}

#body-viewer, #body-editor { 
    overflow-y: auto;
    background: transparent;
    min-height: 0;
    max-width: 100%;
}

.body-viewer {
    padding: 1.5rem 2rem;
    font-size: 1.1rem;
    line-height: 1.6;
    color: var(--md-sys-color-on-surface);
    max-width: 100%;
    overflow-x: auto;
}

/* Toast UI Viewer Overrides to match theme */
.toastui-editor-contents {
    font-family: inherit !important;
    font-size: inherit !important;
    color: inherit !important;
}

/* Icon alignment */
.material-symbols-rounded {
    font-size: 1.5rem;
    vertical-align: middle;
}

.btn-primary {
    background: var(--md-sys-color-primary) !important;
    color: var(--md-sys-color-on-primary) !important;
}

/* Toast UI Editor Styles */
.toastui-editor-defaultUI {
    border: none !important;
}

.toastui-editor-toolbar {
    background-color: var(--md-sys-color-surface) !important;
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant) !important; /* 1px */
}

/* Metadata Form */
#metadata-form {
    max-height: 35vh; /* Using vh for a more reliable constraint than % */
    overflow-y: auto;
    background: var(--md-sys-color-surface);
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
}

/* View-only state for metadata */
#metadata-form.view-only {
    opacity: 0.9;
}

#metadata-form.view-only .meta-input {
    pointer-events: none;
    background: transparent !important;
    border-color: transparent !important;
}

#metadata-form.view-only #btn-add-prop,
#metadata-form.view-only .btn-delete-prop {
    display: none !important;
}

.metadata-form {
    padding: 1rem 1.5rem; /* 16px 24px */
}

.meta-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem; /* 16px */
    cursor: pointer;
    user-select: none;
}

.meta-title {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--md-sys-color-on-surface);
    display: flex;
    align-items: center;
    letter-spacing: 0.0125rem; /* 0.2px */
}

.meta-toggle-icon {
    margin-right: 0.75rem; /* 12px */
    width: 1.5rem;
    font-size: 1.5rem !important;
    color: var(--md-sys-color-outline);
    transition: transform 0.2s ease;
    transform: rotate(-90deg); /* Start collapsed */
    display: inline-block;
}

.btn-add-prop {
    font-size: 0.75rem;
    padding: 0.375rem 1rem; /* 6px 16px */
    height: 2rem; /* 32px */
    background: transparent;
    border: 0.0625rem solid var(--md-sys-color-outline); /* 1px */
    color: var(--md-sys-color-primary);
}

.btn-add-prop:hover {
    background: color-mix(in srgb, var(--md-sys-color-primary) 8%, transparent);
    border-color: var(--md-sys-color-primary);
}

#fields-container {
    display: flex;
    flex-direction: column;
    gap: 0.25rem; /* 4px */
    padding-bottom: 0.5rem; /* 8px */
}

.meta-field {
    display: grid;
    grid-template-columns: 7.5rem 1fr 2.5rem; /* 120px 1fr 40px */
    align-items: center;
    gap: 0.75rem; /* 12px */
    padding: 0.25rem 0.5rem; /* 4px 8px */
    border-radius: 0.5rem; /* 8px */
    transition: background-color 0.15s ease;
}

.meta-field:hover {
    background-color: color-mix(in srgb, var(--md-sys-color-on-surface) 4%, transparent);
}

.meta-label {
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--md-sys-color-secondary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-align: right;
}

.meta-input {
    width: 100%;
    padding: 0.5rem 0.75rem !important; /* 8px 12px */
    font-size: 0.9rem;
    border-radius: 0.25rem !important; /* 4px */
    border: 0.0625rem solid transparent !important; /* 1px */
    background: color-mix(in srgb, var(--md-sys-color-on-surface) 6%, transparent) !important;
    box-sizing: border-box;
}

.meta-input-number {
    max-width: 6.25rem; /* 100px */
}

.meta-input-date {
    max-width: 10rem; /* 160px */
}

.meta-input-text {
    max-width: 100%;
}

.meta-input:focus {
    background: var(--md-sys-color-surface) !important;
    border-color: var(--md-sys-color-primary) !important;
    box-shadow: 0 0 0 0.125rem color-mix(in srgb, var(--md-sys-color-primary) 15%, transparent); /* 2px */
}

/* Checkbox specific sizing */
.meta-input[type="checkbox"] {
    width: 1.125rem; /* 18px */
    height: 1.125rem; /* 18px */
    margin: 0;
    cursor: pointer;
    justify-self: start;
}

.btn-delete-prop {
    opacity: 0.6;
    background: transparent !important;
    color: var(--md-sys-color-outline) !important;
    padding: 0.5rem !important; /* 8px */
    font-size: 0.875rem; /* 14px */
    transition: opacity 0.2s, color 0.2s;
}

.btn-delete-prop:hover {
    opacity: 1;
    color: var(--md-sys-color-error) !important;
    background: color-mix(in srgb, var(--md-sys-color-error) 10%, transparent) !important;
}

.empty-meta-msg {
    color: var(--md-sys-color-outline);
    padding: 1.25rem; /* 20px */
}

/* --- M3 Base Elements --- */
button {
    font-family: var(--md-sys-typescale-body-large-font);
    font-weight: 500;
    border-radius: var(--md-sys-shape-corner-full);
    border: none;
    padding: 0.625rem 1.5rem; /* 10px 24px */
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s, filter 0.2s;
    background: var(--md-sys-color-secondary-container);
    color: var(--md-sys-color-on-secondary-container);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem; /* 8px */
}

button:hover {
    box-shadow: var(--md-sys-elevation-1);
    filter: brightness(0.95);
}

button:disabled {
    background: var(--md-sys-color-surface-variant) !important;
    color: var(--md-sys-color-outline) !important;
    cursor: not-allowed;
    box-shadow: none;
    filter: none;
}

input, select, textarea {
    font-family: inherit;
    padding: 0.75rem 1rem; /* 12px 16px */
    border-radius: var(--md-sys-shape-corner-small);
    border: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    background: color-mix(in srgb, var(--md-sys-color-primary) 3%, #ffffff);
    color: var(--md-sys-color-on-surface);
    box-sizing: border-box;
    transition: border-color 0.2s, background-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus, textarea:focus {
    outline: none;
    border-color: var(--md-sys-color-primary);
    background: #ffffff;
    box-shadow: 0 0 0 0.25rem color-mix(in srgb, var(--md-sys-color-primary) 15%, transparent);
}

/* Header & Footer */
.editor-header {
    padding: 0.75rem 1rem; /* 12px 16px */
    border-bottom: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    display: flex;
    gap: 0.5rem; /* 8px */
    background: var(--md-sys-color-surface);
}

#btn-save, #btn-submit-create {
    background: var(--md-sys-color-primary);
    color: var(--md-sys-color-on-primary);
}

.btn-delete {
    background: var(--md-sys-color-error) !important;
    color: var(--md-sys-color-on-error) !important;
    margin-left: auto;
}

.editor-footer {
    padding: 0.625rem; /* 10px */
    font-size: 0.75rem;
    color: var(--md-sys-color-outline);
    border-top: 0.0625rem solid var(--md-sys-color-surface-variant); /* 1px */
    background: var(--md-sys-color-surface-variant);
    text-align: right;
    height: 2.1875rem; /* 35px */
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

/* Create Note View */
.create-view {
    display: grid;
    place-items: center;
    height: 100%;
    width: 100%;
    background: var(--md-sys-color-surface);
}

.create-form {
    display: grid;
    gap: 1.25rem;
    width: 100%;
    max-width: 25rem; /* 400px */
    padding: 2.5rem;
    background: var(--md-sys-color-surface-variant);
    border-radius: var(--md-sys-shape-corner-extra-large);
    box-shadow: var(--md-sys-elevation-2);
}

.create-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Utility */
.hidden {
    display: none !important;
}

.mobile-only {
    display: none !important;
}

@media (max-width: 48rem) {
    .mobile-only {
        display: inline-flex !important;
    }
}

.sync-status {
    font-size: 0.6rem;
    color: var(--md-sys-color-outline);
}

/* Toast */
.toast {
    position: absolute;
    top: 1.25rem; /* 20px */
    left: 1.25rem; /* 20px */
    background: var(--md-sys-color-primary-container);
    color: var(--md-sys-color-on-primary-container);
    padding: 0.75rem 1.5rem; /* 12px 24px */
    border-radius: var(--md-sys-shape-corner-medium);
    box-shadow: var(--md-sys-elevation-2);
    opacity: 0;
    transform: translateX(-1.25rem); /* -20px */
    transition: opacity 0.3s ease, transform 0.3s ease;
    z-index: 1000;
    pointer-events: none;
}

.toast.show {
    opacity: 1;
    transform: translateX(0);
}

.toast.error {
    background: var(--md-sys-color-error);
    color: var(--md-sys-color-on-error);
}

/* 6. Dataview Styles */
.dv-container {
    margin: 1.5rem 0;
    padding: 1rem;
    background: color-mix(in srgb, var(--md-sys-color-primary) 3%, #ffffff);
    border-radius: var(--md-sys-shape-corner-medium);
    border: 0.0625rem solid var(--md-sys-color-surface-variant);
    min-height: 3rem;
    position: relative;
    transition: opacity 0.3s ease;
}

.dv-container.loading {
    opacity: 0.6;
}

.dv-loading {
    font-size: 0.85rem;
    color: var(--md-sys-color-outline);
    font-style: italic;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.dv-loading::before {
    content: "";
    width: 1rem;
    height: 1rem;
    border: 0.125rem solid var(--md-sys-color-primary);
    border-top-color: transparent;
    border-radius: 50%;
    animation: dv-spin 1s linear infinite;
}

@keyframes dv-spin {
    to { transform: rotate(360deg); }
}

.dv-empty {
    color: var(--md-sys-color-outline);
    font-style: italic;
}

.dv-error {
    color: var(--md-sys-color-error);
    font-size: 0.85rem;
    padding: 0.5rem;
    border-left: 0.25rem solid var(--md-sys-color-error);
}

.dv-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0.5rem 0;
}

.dv-table th {
    text-align: left;
    padding: 0.75rem;
    border-bottom: 0.125rem solid var(--md-sys-color-surface-variant);
    font-weight: 600;
    color: var(--md-sys-color-secondary);
    font-size: 0.9rem;
}

.dv-table td {
    padding: 0.75rem;
